      panel.append(
        button("Прочитать текущую версию","wo-private-current",()=>{const id=selectedId();if(id)return readPrivate(id,0);}),
        button("Прочитать указанную версию","wo-private-known",()=>{const id=selectedId();if(!id)return;let v;try{v=inputNumber(version.value,1,1000);}catch(e){version.setAttribute("aria-invalid","true");notice(e.message,true);version.focus();return;}version.removeAttribute("aria-invalid");return readPrivate(id,v);}),
        button("Скрыть закрытые сведения","wo-private-clear",()=>{clearPrivate();notice("Закрытые сведения скрыты.");}),
        button("Скачать текущую версию (PDF)","wo-private-export",()=>{const id=selectedId();if(id)return download("work/orders/"+id+"/appendix/export","application/pdf");}),
        button("Скачать указанную версию (PDF)","wo-private-known-export",()=>{const id=selectedId();if(!id)return;let v;try{v=inputNumber(version.value,1,1000);}catch(e){version.setAttribute("aria-invalid","true");notice("Укажите целую версию от 1 до 1000.",true);version.focus();return;}version.removeAttribute("aria-invalid");return download("work/orders/"+id+"/appendix-versions/"+v+"/export","application/pdf");})
      );
      if(!choices.size)panel.append(node("p","Загрузите принятые допуски или укажите известный идентификатор наряда. Сам факт роли не открывает приложение."));
      if(privateValue){const block=node("section","","wo-private","wo-private-text");block.append(node("h4","Закрытое приложение · версия "+privateValue.version),node("p",privateValue.privateText,"wo-preserve"));support(block,{"Наряд":privateValue.workOrderId,"Автор":privateValue.authorAccountId});panel.append(block);}
