    async function readPrivate(id,version){try{uuid(id);}catch(_){notice("Выберите наряд.",true);return;}await read(async fresh=>{const v=appendixDTO(await api("work/orders/"+id+(version?"/appendix-versions/"+integer(version,1,1000):"/appendix")),true);if(v.workOrderId!==id||version&&v.version!==version)throw fail();if(!fresh())return;privateValue=v;render();const expiry=selectedPermit?.workOrderId===id?Date.parse(selectedPermit.expiresAt)-Date.now():60000;privateTimer=setTimeout(()=>{clearPrivate();notice("Закрытые сведения скрыты по истечении времени просмотра. Для продолжения запросите их заново.");},Math.max(0,Math.min(60000,expiry)));});}
