      if(c.kind==="crew.create"||c.kind==="resource.create"){const kind=c.kind.split(".")[0];r=simpleDTO(value,kind,s);if(r.revision!==1||r.state!=="Active"||r.createdBy!==c.accountId||r.name!==b.name||kind==="crew"&&r.leaderAccountId!==b.leaderAccountId||kind==="resource"&&r.capacity!==b.capacity)throw fail();return r;}
